window.POLICY["pol_admin.html"] = {"title": "픽콕 리워드 어드민 기능정책서 v0.2 v0.3", "s": {"s1": {"t": "제1조 (목적과 범위)", "h": "<h3 id=\"s1-1\">1-1. 목적</h3>\n<p>고객이 <strong>출석·퀴즈·혜택·친구 추천·숙소 예약</strong>으로 쌓은 포인트를\n운영자가 <strong>확인·조정·지급</strong>하고, 적립 거리를 <strong>개발자 없이</strong> 넣고 뺄 수 있게 한다.</p>\n<h3 id=\"s1-2\">1-2. 메뉴 구조 (1뎁스 12개)</h3>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:center\">#</th>\n  <th>메뉴</th>\n  <th>화면 키</th>\n  <th>하는 일</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:center\">1</td>\n  <td>대시보드</td>\n  <td><code>dash</code></td>\n  <td>전체 현황과 처리 대기 건을 한눈에 본다</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">2</td>\n  <td>회원 목록</td>\n  <td><code>users</code></td>\n  <td>회원 조회·상세·포인트 수동 처리</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">3</td>\n  <td>전체 포인트 내역</td>\n  <td><code>ledger</code></td>\n  <td>포인트가 움직인 <strong>모든 기록</strong>(원장)</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">4</td>\n  <td>출금 신청</td>\n  <td><code>withdrawals</code></td>\n  <td>현금 출금 신청을 지급하거나 반려</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">5</td>\n  <td>픽샵 구매내역</td>\n  <td><code>orders</code></td>\n  <td>포인트로 바꾼 쿠폰 내역</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">6</td>\n  <td>예약 적립</td>\n  <td><code>bookings</code></td>\n  <td>숙소 예약으로 생긴 적립</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">7</td>\n  <td>혜택(오퍼월)</td>\n  <td><code>offers</code></td>\n  <td>광고 등록·노출 관리</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">8</td>\n  <td>퀴즈 관리</td>\n  <td><code>quiz</code></td>\n  <td>문항 등록·출제 관리</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">9</td>\n  <td>광고주 관리</td>\n  <td><code>advertisers</code></td>\n  <td>광고를 올릴 수 있는 주체 등록</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">10</td>\n  <td>알림</td>\n  <td><code>notify</code></td>\n  <td>고객 앱 알림 발송·이력</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">11</td>\n  <td>설정</td>\n  <td><code>settings</code></td>\n  <td>적립·출금 정책값 변경</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">12</td>\n  <td>관리자 로그</td>\n  <td><code>logs</code></td>\n  <td>운영자가 한 일의 기록</td>\n</tr>\n</tbody>\n</table>\n<h3 id=\"s1-3\">1-3. 이번 버전에 넣지 않은 것</h3>\n<p>화면마다 <strong>안내 띠</strong>로 운영자에게 직접 알린다 (3-2 참조). 아래가 전부다.</p>\n<table>\n<thead>\n<tr>\n  <th>메뉴</th>\n  <th>빠진 것</th>\n  <th>왜</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>회원</td>\n  <td>회원 등급·세그먼트</td>\n  <td>멤버십 정책 확정 후</td>\n</tr>\n<tr>\n  <td>회원</td>\n  <td>탈퇴 회원 조회</td>\n  <td>탈퇴 시 즉시 삭제 정책이라 목록에 남기지 않음</td>\n</tr>\n<tr>\n  <td>회원</td>\n  <td>엑셀 내려받기</td>\n  <td><strong>개인정보 반출 기준</strong>을 먼저 정해야 함</td>\n</tr>\n<tr>\n  <td>출금</td>\n  <td>자동 송금(펌뱅킹)</td>\n  <td>현재는 운영자가 확인 후 [지급하기]</td>\n</tr>\n<tr>\n  <td>출금</td>\n  <td>금액 한도·승인 단계</td>\n  <td>일정 금액 이상 승인 여부 <strong>미결</strong></td>\n</tr>\n<tr>\n  <td>출금</td>\n  <td>원천징수·세무 처리</td>\n  <td>현금 지급이라 <strong>세무 기준 미결</strong></td>\n</tr>\n<tr>\n  <td>픽샵</td>\n  <td>쿠폰 발행사 연동</td>\n  <td><strong>발행 업체 미정</strong> — 현재 쿠폰번호를 자사에서 생성</td>\n</tr>\n<tr>\n  <td>픽샵</td>\n  <td>재고·정산 연동</td>\n  <td>업체 확정 후</td>\n</tr>\n<tr>\n  <td>혜택</td>\n  <td>성과 리포트(노출·클릭·전환)</td>\n  <td>다음 버전</td>\n</tr>\n<tr>\n  <td>혜택</td>\n  <td>정산 연동</td>\n  <td>요율·회계 기준 확정 후</td>\n</tr>\n<tr>\n  <td>광고주</td>\n  <td>정산·과금(CPC/CPA·세금계산서)</td>\n  <td>요율·회계 기준 <strong>미결</strong></td>\n</tr>\n<tr>\n  <td>광고주</td>\n  <td>광고주 직접 접속 계정</td>\n  <td>다음 단계</td>\n</tr>\n<tr>\n  <td>광고주</td>\n  <td>계약 기간 관리</td>\n  <td>현재는 혜택의 노출기간으로 대신함</td>\n</tr>\n<tr>\n  <td>알림</td>\n  <td>휴대폰 푸시</td>\n  <td>앱 출시와 함께</td>\n</tr>\n<tr>\n  <td>알림</td>\n  <td>예약 발송·세그먼트</td>\n  <td>다음 버전</td>\n</tr>\n<tr>\n  <td>알림</td>\n  <td>수신 동의 연동</td>\n  <td>광고성 알림 발송 규칙 <strong>미결</strong></td>\n</tr>\n<tr>\n  <td>로그</td>\n  <td>처리자 구분</td>\n  <td>비밀번호 1개 방식이라 <strong>누가 했는지 구분 못 함</strong></td>\n</tr>\n</tbody>\n</table>\n<hr />"}, "s1-1": {"t": "1-1. 목적", "h": "<p>고객이 <strong>출석·퀴즈·혜택·친구 추천·숙소 예약</strong>으로 쌓은 포인트를\n운영자가 <strong>확인·조정·지급</strong>하고, 적립 거리를 <strong>개발자 없이</strong> 넣고 뺄 수 있게 한다.</p>"}, "s1-2": {"t": "1-2. 메뉴 구조 (1뎁스 12개)", "h": "<table>\n<thead>\n<tr>\n  <th style=\"text-align:center\">#</th>\n  <th>메뉴</th>\n  <th>화면 키</th>\n  <th>하는 일</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:center\">1</td>\n  <td>대시보드</td>\n  <td><code>dash</code></td>\n  <td>전체 현황과 처리 대기 건을 한눈에 본다</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">2</td>\n  <td>회원 목록</td>\n  <td><code>users</code></td>\n  <td>회원 조회·상세·포인트 수동 처리</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">3</td>\n  <td>전체 포인트 내역</td>\n  <td><code>ledger</code></td>\n  <td>포인트가 움직인 <strong>모든 기록</strong>(원장)</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">4</td>\n  <td>출금 신청</td>\n  <td><code>withdrawals</code></td>\n  <td>현금 출금 신청을 지급하거나 반려</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">5</td>\n  <td>픽샵 구매내역</td>\n  <td><code>orders</code></td>\n  <td>포인트로 바꾼 쿠폰 내역</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">6</td>\n  <td>예약 적립</td>\n  <td><code>bookings</code></td>\n  <td>숙소 예약으로 생긴 적립</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">7</td>\n  <td>혜택(오퍼월)</td>\n  <td><code>offers</code></td>\n  <td>광고 등록·노출 관리</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">8</td>\n  <td>퀴즈 관리</td>\n  <td><code>quiz</code></td>\n  <td>문항 등록·출제 관리</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">9</td>\n  <td>광고주 관리</td>\n  <td><code>advertisers</code></td>\n  <td>광고를 올릴 수 있는 주체 등록</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">10</td>\n  <td>알림</td>\n  <td><code>notify</code></td>\n  <td>고객 앱 알림 발송·이력</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">11</td>\n  <td>설정</td>\n  <td><code>settings</code></td>\n  <td>적립·출금 정책값 변경</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">12</td>\n  <td>관리자 로그</td>\n  <td><code>logs</code></td>\n  <td>운영자가 한 일의 기록</td>\n</tr>\n</tbody>\n</table>"}, "s1-3": {"t": "1-3. 이번 버전에 넣지 않은 것", "h": "<p>화면마다 <strong>안내 띠</strong>로 운영자에게 직접 알린다 (3-2 참조). 아래가 전부다.</p>\n<table>\n<thead>\n<tr>\n  <th>메뉴</th>\n  <th>빠진 것</th>\n  <th>왜</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>회원</td>\n  <td>회원 등급·세그먼트</td>\n  <td>멤버십 정책 확정 후</td>\n</tr>\n<tr>\n  <td>회원</td>\n  <td>탈퇴 회원 조회</td>\n  <td>탈퇴 시 즉시 삭제 정책이라 목록에 남기지 않음</td>\n</tr>\n<tr>\n  <td>회원</td>\n  <td>엑셀 내려받기</td>\n  <td><strong>개인정보 반출 기준</strong>을 먼저 정해야 함</td>\n</tr>\n<tr>\n  <td>출금</td>\n  <td>자동 송금(펌뱅킹)</td>\n  <td>현재는 운영자가 확인 후 [지급하기]</td>\n</tr>\n<tr>\n  <td>출금</td>\n  <td>금액 한도·승인 단계</td>\n  <td>일정 금액 이상 승인 여부 <strong>미결</strong></td>\n</tr>\n<tr>\n  <td>출금</td>\n  <td>원천징수·세무 처리</td>\n  <td>현금 지급이라 <strong>세무 기준 미결</strong></td>\n</tr>\n<tr>\n  <td>픽샵</td>\n  <td>쿠폰 발행사 연동</td>\n  <td><strong>발행 업체 미정</strong> — 현재 쿠폰번호를 자사에서 생성</td>\n</tr>\n<tr>\n  <td>픽샵</td>\n  <td>재고·정산 연동</td>\n  <td>업체 확정 후</td>\n</tr>\n<tr>\n  <td>혜택</td>\n  <td>성과 리포트(노출·클릭·전환)</td>\n  <td>다음 버전</td>\n</tr>\n<tr>\n  <td>혜택</td>\n  <td>정산 연동</td>\n  <td>요율·회계 기준 확정 후</td>\n</tr>\n<tr>\n  <td>광고주</td>\n  <td>정산·과금(CPC/CPA·세금계산서)</td>\n  <td>요율·회계 기준 <strong>미결</strong></td>\n</tr>\n<tr>\n  <td>광고주</td>\n  <td>광고주 직접 접속 계정</td>\n  <td>다음 단계</td>\n</tr>\n<tr>\n  <td>광고주</td>\n  <td>계약 기간 관리</td>\n  <td>현재는 혜택의 노출기간으로 대신함</td>\n</tr>\n<tr>\n  <td>알림</td>\n  <td>휴대폰 푸시</td>\n  <td>앱 출시와 함께</td>\n</tr>\n<tr>\n  <td>알림</td>\n  <td>예약 발송·세그먼트</td>\n  <td>다음 버전</td>\n</tr>\n<tr>\n  <td>알림</td>\n  <td>수신 동의 연동</td>\n  <td>광고성 알림 발송 규칙 <strong>미결</strong></td>\n</tr>\n<tr>\n  <td>로그</td>\n  <td>처리자 구분</td>\n  <td>비밀번호 1개 방식이라 <strong>누가 했는지 구분 못 함</strong></td>\n</tr>\n</tbody>\n</table>\n<hr />"}, "s2": {"t": "제2조 (로그인과 권한)", "h": "<h3 id=\"s2-1\">2-1. 로그인</h3>\n<ul>\n<li><strong>비밀번호 하나</strong>로 들어간다. 계정 구분이 없다.</li>\n<li>비밀번호는 설정(<code>admin_pw</code>)에서 바꾼다.</li>\n</ul>\n<h3 id=\"s2-2\">2-2. 권한 — 현재 없음</h3>\n<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>현재</th>\n  <th>정해야 할 것</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>계정 구분</td>\n  <td>없음 (단일 비밀번호)</td>\n  <td>운영자별 계정 발급 여부</td>\n</tr>\n<tr>\n  <td>권한 등급</td>\n  <td>없음 (들어오면 전부 가능)</td>\n  <td>조회 전용 / 처리 가능 구분</td>\n</tr>\n<tr>\n  <td>처리자 기록</td>\n  <td><strong>남지 않음</strong></td>\n  <td>관리자 로그에 처리자를 남기는 방식</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><code>미결</code> — <strong>포인트 수동 지급·회수와 출금 지급은 돈이 움직이는 행위</strong>인데\n지금은 <strong>누가 했는지 알 수 없다.</strong> 권한 체계와 함께 정해야 한다.</p>\n</blockquote>\n<h3 id=\"s2-3\">2-3. 로그인 직후 안내</h3>\n<p>로그인하면 <strong>안내 팝업</strong>이 한 번 뜬다 (탭마다 1회).\n이번 버전의 성격(시연용·가상 데이터)과 빠진 기능이 있다는 점을 먼저 알리고,\n<strong>기능정책서로 가는 링크</strong>를 둔다.</p>\n<blockquote>\n<p><strong>왜</strong> — 운영자가 완성된 어드민으로 알고 들어오면\n빠진 기능마다 문의가 발생한다. <strong>미리 알리는 편이 싸다.</strong></p>\n</blockquote>\n<hr />"}, "s2-1": {"t": "2-1. 로그인", "h": "<ul>\n<li><strong>비밀번호 하나</strong>로 들어간다. 계정 구분이 없다.</li>\n<li>비밀번호는 설정(<code>admin_pw</code>)에서 바꾼다.</li>\n</ul>"}, "s2-2": {"t": "2-2. 권한 — 현재 없음", "h": "<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>현재</th>\n  <th>정해야 할 것</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>계정 구분</td>\n  <td>없음 (단일 비밀번호)</td>\n  <td>운영자별 계정 발급 여부</td>\n</tr>\n<tr>\n  <td>권한 등급</td>\n  <td>없음 (들어오면 전부 가능)</td>\n  <td>조회 전용 / 처리 가능 구분</td>\n</tr>\n<tr>\n  <td>처리자 기록</td>\n  <td><strong>남지 않음</strong></td>\n  <td>관리자 로그에 처리자를 남기는 방식</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><code>미결</code> — <strong>포인트 수동 지급·회수와 출금 지급은 돈이 움직이는 행위</strong>인데\n지금은 <strong>누가 했는지 알 수 없다.</strong> 권한 체계와 함께 정해야 한다.</p>\n</blockquote>"}, "s2-3": {"t": "2-3. 로그인 직후 안내", "h": "<p>로그인하면 <strong>안내 팝업</strong>이 한 번 뜬다 (탭마다 1회).\n이번 버전의 성격(시연용·가상 데이터)과 빠진 기능이 있다는 점을 먼저 알리고,\n<strong>기능정책서로 가는 링크</strong>를 둔다.</p>\n<blockquote>\n<p><strong>왜</strong> — 운영자가 완성된 어드민으로 알고 들어오면\n빠진 기능마다 문의가 발생한다. <strong>미리 알리는 편이 싸다.</strong></p>\n</blockquote>\n<hr />"}, "s3": {"t": "제3조 (모든 화면에 공통인 규칙)", "h": "<blockquote>\n<p>2026-10-12 CPO 피드백으로 <strong>12개 화면의 모양을 하나로 맞췄다.</strong>\n화면마다 다르면 운영자가 화면마다 다시 배워야 한다.</p>\n</blockquote>\n<h3 id=\"s3-1\">3-1. 찾기 (9개 화면)</h3>\n<p>적용: 회원 · 포인트 내역 · 출금 · 픽샵 · 예약 적립 · 혜택 · 퀴즈 · 알림 · 로그\n(대시보드 · 광고주 · 설정은 <strong>찾을 대상이 아니라서</strong> 두지 않는다)</p>\n<table>\n<thead>\n<tr>\n  <th>규칙</th>\n  <th>내용</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>자리</td>\n  <td><strong>왼쪽에 전체 건수</strong>, 오른쪽에 찾는 칸</td>\n</tr>\n<tr>\n  <td>칸 이름</td>\n  <td>칸마다 이름을 <strong>작게 위에</strong> 붙인다</td>\n</tr>\n<tr>\n  <td>구분</td>\n  <td><strong>쳐서 찾는 칸</strong>(입력)과 <strong>골라서 거르는 칸</strong>(선택)을 나눈다</td>\n</tr>\n<tr>\n  <td>날짜</td>\n  <td>날짜가 둘 이상이면 <strong>어느 날짜로 찾을지 먼저 고른 뒤</strong> 달력을 연다</td>\n</tr>\n<tr>\n  <td>실행</td>\n  <td>조건을 다 고른 뒤 <strong>[조회]</strong> 를 눌러야 걸린다. [초기화]로 전부 푼다</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>왜 [조회] 버튼인가</strong> — 고를 때마다 즉시 걸면 <strong>중간 단계마다 화면이 다시 그려진다.</strong>\n조건을 다 고르기 전의 결과는 볼 이유가 없다. (CPO 제안 · 2026-10-12 확정)</p>\n</blockquote>\n<h3 id=\"s3-2\">3-2. 안내 띠</h3>\n<ul>\n<li>자리: <strong>페이지 제목·설명 바로 아래</strong></li>\n<li>두 종류: <code>ℹ️ 이번 버전에 들어가지 않은 것</code> / <code>📌 이 화면을 읽는 법</code></li>\n<li>접혀 있다가 눌러서 펼친다. 끝에 <strong>기능정책서 링크</strong>가 붙는다</li>\n<li><strong>공지·참고 사항도 같은 모양으로 통일</strong>한다</li>\n</ul>\n<h3 id=\"s3-3\">3-3. 요약 세 칸</h3>\n<p>요약이 있는 화면은 <strong>총 누적 · 사용(나간 것) · 잔여(남은 것)</strong> 틀로 읽는다.</p>\n<table>\n<thead>\n<tr>\n  <th>화면</th>\n  <th>칸1</th>\n  <th>칸2</th>\n  <th>칸3</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>포인트 내역</td>\n  <td>총 적립 포인트</td>\n  <td>총 사용 포인트</td>\n  <td>현재 잔액</td>\n</tr>\n<tr>\n  <td>출금 신청</td>\n  <td>누적 송금액</td>\n  <td>반려 환불액</td>\n  <td>대기 금액</td>\n</tr>\n<tr>\n  <td>픽샵 구매내역</td>\n  <td>총 구매 포인트</td>\n  <td>사용완료</td>\n  <td>미사용</td>\n</tr>\n<tr>\n  <td>예약 적립</td>\n  <td>총 적립 포인트</td>\n  <td>뽑기로 지급</td>\n  <td>미수령 뽑기</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><strong>요약은 거르기와 무관하게 항상 전체 기준</strong>이다</li>\n<li>픽샵의 「총 구매」는 <strong>취소분을 뺀 값</strong>이다</li>\n</ul>\n<blockquote>\n<p><strong>왜 미사용을 따로 보나</strong> — 픽샵의 미사용 금액은\n<strong>앞으로 쿠폰 업체에 정산해야 할 채무</strong>다. 쓴 것과 섞으면 남은 채무를 알 수 없다.</p>\n</blockquote>\n<h3 id=\"s3-4\">3-4. 불러오는 중</h3>\n<ul>\n<li>자료를 가져오는 데 <strong>0.22초를 넘길 때만</strong> 자리를 잡는 회색 틀이 나온다</li>\n<li>그보다 빠르면 <strong>아무것도 보이지 않는다</strong></li>\n<li>못 가져온 경우에는 <strong>사유와 [다시 시도] 버튼</strong>이 나온다</li>\n</ul>\n<blockquote>\n<p><strong>왜 지연 방식인가</strong> — 실측 결과 화면 전환이 <strong>29~101ms</strong>였다.\n무조건 띄우면 번쩍거려 오히려 지저분하다.</p>\n</blockquote>\n<h3 id=\"s3-5\">3-5. 모달(팝업) 공통 규칙 <em>(v0.2 신설 · 화면기획서 C-LAYER R9·R10)</em></h3>\n<table>\n<thead>\n<tr>\n  <th>규칙</th>\n  <th>내용</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>버튼 순서</td>\n  <td>두 버튼이 나란히 있으면 <strong>[취소] [실행]</strong> — 왼쪽이 취소(회색), 오른쪽이 실행(강조색). 위험한 실행(반려·초기화)은 빨간색</td>\n</tr>\n<tr>\n  <td>실행 버튼 잠금</td>\n  <td>실행을 누르면 <strong>팝업의 버튼이 모두 잠기고</strong> 글자가 <strong>「처리 중…」</strong> 으로 바뀐다. 서버 응답이 오면 풀린다 — 두 번 눌러 두 번 처리되는 것을 막는다</td>\n</tr>\n<tr>\n  <td>배경 클릭</td>\n  <td><strong>입력칸이 있는 팝업은 배경을 눌러도 닫히지 않는다</strong> (적던 내용이 사라지므로). 입력칸이 없는 팝업은 배경을 누르면 닫힌다</td>\n</tr>\n<tr>\n  <td>확인창</td>\n  <td>브라우저 기본 확인창(confirm·prompt)을 쓰지 않는다 — 출금 <strong>[지급하기]</strong> 는 「지급 처리」 팝업(회원·금액·입금 계좌 + 「실제로 송금을 마치셨나요? 지급완료로 기록됩니다.」), 쿠폰 <strong>[재발행]</strong> 은 「쿠폰 재발행」 팝업(「쿠폰을 새로 발행합니다. 고객에게 알림이 갑니다.」)</td>\n</tr>\n</tbody>\n</table>\n<hr />"}, "s3-1": {"t": "3-1. 찾기 (9개 화면)", "h": "<p>적용: 회원 · 포인트 내역 · 출금 · 픽샵 · 예약 적립 · 혜택 · 퀴즈 · 알림 · 로그\n(대시보드 · 광고주 · 설정은 <strong>찾을 대상이 아니라서</strong> 두지 않는다)</p>\n<table>\n<thead>\n<tr>\n  <th>규칙</th>\n  <th>내용</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>자리</td>\n  <td><strong>왼쪽에 전체 건수</strong>, 오른쪽에 찾는 칸</td>\n</tr>\n<tr>\n  <td>칸 이름</td>\n  <td>칸마다 이름을 <strong>작게 위에</strong> 붙인다</td>\n</tr>\n<tr>\n  <td>구분</td>\n  <td><strong>쳐서 찾는 칸</strong>(입력)과 <strong>골라서 거르는 칸</strong>(선택)을 나눈다</td>\n</tr>\n<tr>\n  <td>날짜</td>\n  <td>날짜가 둘 이상이면 <strong>어느 날짜로 찾을지 먼저 고른 뒤</strong> 달력을 연다</td>\n</tr>\n<tr>\n  <td>실행</td>\n  <td>조건을 다 고른 뒤 <strong>[조회]</strong> 를 눌러야 걸린다. [초기화]로 전부 푼다</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>왜 [조회] 버튼인가</strong> — 고를 때마다 즉시 걸면 <strong>중간 단계마다 화면이 다시 그려진다.</strong>\n조건을 다 고르기 전의 결과는 볼 이유가 없다. (CPO 제안 · 2026-10-12 확정)</p>\n</blockquote>"}, "s3-2": {"t": "3-2. 안내 띠", "h": "<ul>\n<li>자리: <strong>페이지 제목·설명 바로 아래</strong></li>\n<li>두 종류: <code>ℹ️ 이번 버전에 들어가지 않은 것</code> / <code>📌 이 화면을 읽는 법</code></li>\n<li>접혀 있다가 눌러서 펼친다. 끝에 <strong>기능정책서 링크</strong>가 붙는다</li>\n<li><strong>공지·참고 사항도 같은 모양으로 통일</strong>한다</li>\n</ul>"}, "s3-3": {"t": "3-3. 요약 세 칸", "h": "<p>요약이 있는 화면은 <strong>총 누적 · 사용(나간 것) · 잔여(남은 것)</strong> 틀로 읽는다.</p>\n<table>\n<thead>\n<tr>\n  <th>화면</th>\n  <th>칸1</th>\n  <th>칸2</th>\n  <th>칸3</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>포인트 내역</td>\n  <td>총 적립 포인트</td>\n  <td>총 사용 포인트</td>\n  <td>현재 잔액</td>\n</tr>\n<tr>\n  <td>출금 신청</td>\n  <td>누적 송금액</td>\n  <td>반려 환불액</td>\n  <td>대기 금액</td>\n</tr>\n<tr>\n  <td>픽샵 구매내역</td>\n  <td>총 구매 포인트</td>\n  <td>사용완료</td>\n  <td>미사용</td>\n</tr>\n<tr>\n  <td>예약 적립</td>\n  <td>총 적립 포인트</td>\n  <td>뽑기로 지급</td>\n  <td>미수령 뽑기</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><strong>요약은 거르기와 무관하게 항상 전체 기준</strong>이다</li>\n<li>픽샵의 「총 구매」는 <strong>취소분을 뺀 값</strong>이다</li>\n</ul>\n<blockquote>\n<p><strong>왜 미사용을 따로 보나</strong> — 픽샵의 미사용 금액은\n<strong>앞으로 쿠폰 업체에 정산해야 할 채무</strong>다. 쓴 것과 섞으면 남은 채무를 알 수 없다.</p>\n</blockquote>"}, "s3-4": {"t": "3-4. 불러오는 중", "h": "<ul>\n<li>자료를 가져오는 데 <strong>0.22초를 넘길 때만</strong> 자리를 잡는 회색 틀이 나온다</li>\n<li>그보다 빠르면 <strong>아무것도 보이지 않는다</strong></li>\n<li>못 가져온 경우에는 <strong>사유와 [다시 시도] 버튼</strong>이 나온다</li>\n</ul>\n<blockquote>\n<p><strong>왜 지연 방식인가</strong> — 실측 결과 화면 전환이 <strong>29~101ms</strong>였다.\n무조건 띄우면 번쩍거려 오히려 지저분하다.</p>\n</blockquote>"}, "s3-5": {"t": "3-5. 모달(팝업) 공통 규칙 (v0.2 신설 · 화면기획서 C-LAYER R9·R10)", "h": "<table>\n<thead>\n<tr>\n  <th>규칙</th>\n  <th>내용</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>버튼 순서</td>\n  <td>두 버튼이 나란히 있으면 <strong>[취소] [실행]</strong> — 왼쪽이 취소(회색), 오른쪽이 실행(강조색). 위험한 실행(반려·초기화)은 빨간색</td>\n</tr>\n<tr>\n  <td>실행 버튼 잠금</td>\n  <td>실행을 누르면 <strong>팝업의 버튼이 모두 잠기고</strong> 글자가 <strong>「처리 중…」</strong> 으로 바뀐다. 서버 응답이 오면 풀린다 — 두 번 눌러 두 번 처리되는 것을 막는다</td>\n</tr>\n<tr>\n  <td>배경 클릭</td>\n  <td><strong>입력칸이 있는 팝업은 배경을 눌러도 닫히지 않는다</strong> (적던 내용이 사라지므로). 입력칸이 없는 팝업은 배경을 누르면 닫힌다</td>\n</tr>\n<tr>\n  <td>확인창</td>\n  <td>브라우저 기본 확인창(confirm·prompt)을 쓰지 않는다 — 출금 <strong>[지급하기]</strong> 는 「지급 처리」 팝업(회원·금액·입금 계좌 + 「실제로 송금을 마치셨나요? 지급완료로 기록됩니다.」), 쿠폰 <strong>[재발행]</strong> 은 「쿠폰 재발행」 팝업(「쿠폰을 새로 발행합니다. 고객에게 알림이 갑니다.」)</td>\n</tr>\n</tbody>\n</table>\n<hr />"}, "s4": {"t": "제4조 (대시보드)", "h": "<h3 id=\"s4-1\">4-1. 구성</h3>\n<table>\n<thead>\n<tr>\n  <th>묶음</th>\n  <th>내용</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>전체 현황</td>\n  <td>전체 회원 · 총 보유 포인트 · 누적 적립 · 누적 사용</td>\n</tr>\n<tr>\n  <td>기간별 현황</td>\n  <td><strong>오늘 / 최근 7일 / 최근 30일</strong> — 가입 · 적립 · 사용 · 건수</td>\n</tr>\n<tr>\n  <td>처리 대기</td>\n  <td>출금·픽샵 신청 중 아직 처리하지 않은 건</td>\n</tr>\n<tr>\n  <td>최근 목록</td>\n  <td>포인트 내역 · 예약 적립 · 픽샵 구매 — <strong>각 8건</strong></td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>왼쪽 메뉴 「출금 신청」에 <strong>대기 건수가 빨간 숫자</strong>로 붙는다</li>\n<li>각 목록 끝에 해당 메뉴로 가는 버튼이 있다</li>\n</ul>\n<blockquote>\n<p><strong>왜 기간을 고르게 했나</strong> — 하루치만 보면 <strong>그날이 많은 날인지 적은 날인지 알 수 없다.</strong>\n비교할 기준이 있어야 숫자가 뜻을 갖는다.</p>\n</blockquote>\n<hr />"}, "s4-1": {"t": "4-1. 구성", "h": "<table>\n<thead>\n<tr>\n  <th>묶음</th>\n  <th>내용</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>전체 현황</td>\n  <td>전체 회원 · 총 보유 포인트 · 누적 적립 · 누적 사용</td>\n</tr>\n<tr>\n  <td>기간별 현황</td>\n  <td><strong>오늘 / 최근 7일 / 최근 30일</strong> — 가입 · 적립 · 사용 · 건수</td>\n</tr>\n<tr>\n  <td>처리 대기</td>\n  <td>출금·픽샵 신청 중 아직 처리하지 않은 건</td>\n</tr>\n<tr>\n  <td>최근 목록</td>\n  <td>포인트 내역 · 예약 적립 · 픽샵 구매 — <strong>각 8건</strong></td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>왼쪽 메뉴 「출금 신청」에 <strong>대기 건수가 빨간 숫자</strong>로 붙는다</li>\n<li>각 목록 끝에 해당 메뉴로 가는 버튼이 있다</li>\n</ul>\n<blockquote>\n<p><strong>왜 기간을 고르게 했나</strong> — 하루치만 보면 <strong>그날이 많은 날인지 적은 날인지 알 수 없다.</strong>\n비교할 기준이 있어야 숫자가 뜻을 갖는다.</p>\n</blockquote>\n<hr />"}, "s5": {"t": "제5조 (회원 관리)", "h": "<h3 id=\"s5-1\">5-1. 목록</h3>\n<p>열: 선택 · <strong>회원ID(이메일)</strong> · 이름 · 본인인증 · 추천코드 · 추천한 친구 · 보유 포인트 · 가입일 · 관리</p>\n<ul>\n<li>찾기: <strong>가입일</strong>(달력) · 본인인증(전체/완료/미완료) · 검색어(이메일·이름·추천코드)</li>\n<li>회원 ID는 <strong>이메일 주소</strong>다. 별도 아이디를 두지 않는다</li>\n<li><strong>보유 포인트 — 적립대기 표시</strong> <em>(v0.2)</em>: <strong>미인증 회원</strong>인데 (원장 잔액 + 적립대기)가 <strong>1 이상</strong>이면 그 합계를 보여주고 오른쪽에 작은 <strong>「적립대기」</strong> 를 붙인다 (예: 「500P 적립대기」). 인증 회원·0P 는 원장 잔액 그대로</li>\n</ul>\n<blockquote>\n<p><strong>적립대기</strong> — 로그인했지만 <strong>본인인증 전</strong>인 회원에게 생긴 적립(예약 적립 · 친구 추천 · 관리자 지급). 원장에 넣지 않고 기다렸다가 <strong>본인인증하는 순간 한꺼번에 지급</strong>한다(기한 없음 · 적립일 = 지급일). 상세는 참여형적립 기능정책서 1-6절</p>\n</blockquote>\n<h3 id=\"s5-2\">5-2. 상세</h3>\n<p>좌우 두 단으로 <strong>기본 정보</strong>와 <strong>포인트 내역</strong>을 함께 본다.</p>\n<ul>\n<li><strong>미인증 회원</strong> <em>(v0.2)</em> — 포인트 요약의 「사용 가능」 대신 <strong>「보유 NP 적립대기」</strong> 를 보여주고, 그 아래 안내\n<strong>「본인인증 전이에요. 아래 포인트는 고객 화면에 보이지 않고, 본인인증을 하면 그때 지급돼요.」</strong> 와\n내역 칩(<strong>예약 · 친구 추천 · 관리자 지급·회수 · 이전에 쌓인 포인트</strong> — 각 금액·건수)을 둔다</li>\n</ul>\n<h3 id=\"s5-3\">5-3. 포인트 수동 지급·회수</h3>\n<ul>\n<li>목록에서 <strong>회원을 골라 한 번에</strong> 처리할 수 있다</li>\n<li><strong>금액과 사유</strong>를 적어야 한다. 사유는 원장에 그대로 남는다</li>\n<li>처리하면 <strong>원장에 한 줄로 쌓이고</strong>, 관리자 로그에도 남는다(<code>point_grant</code>)</li>\n<li><strong>미인증 회원</strong> <em>(v0.2 · PO 확정 2026-10-27)</em> — 지급·회수할 수 있다. 다만 <strong>적립대기로 들어가고</strong>, 본인인증을 해야 고객 화면에 보이고 실제로 적립된다<ul>\n<li>미인증 회원에게는 지급·회수 <strong>알림을 보내지 않는다</strong> (금액이 드러나므로). 인증으로 지급될 때 「적립대기 포인트 +NP」 1건</li>\n<li>회수는 <strong>(원장 잔액 + 적립대기) 안에서만</strong> — 넘으면 「회수할 포인트가 모자라요 (적립대기 포함)」</li>\n<li>결과 안내: 단건 「본인인증 전 회원이라 적립대기로 넣었어요 · 인증하면 지급돼요」 / 일괄 「N명 처리 완료 · 그중 N명은 본인인증 전이라 적립대기」</li>\n</ul>\n</li>\n</ul>\n<blockquote>\n<p><code>미결</code> — <strong>권한·한도·처리자 기록</strong>이 정해지지 않았다.\n지금은 누구나 금액 제한 없이 지급·회수할 수 있다. (2-2 참조)</p>\n</blockquote>\n<h3 id=\"s5-4\">5-4. 본인인증 처리 <em>(v0.2 신설)</em></h3>\n<ul>\n<li>회원 상세에서 관리자가 본인인증 상태를 <strong>완료</strong>로 바꿀 수 있다 (시연용)</li>\n<li>완료로 바꾸면 <strong>고객이 직접 인증한 것과 같이 적립대기를 지급</strong>한다 · 관리자 로그에 「본인인증 완료 · 적립대기 NP 지급」</li>\n<li><strong>화면</strong> <em>(10-28 추가 — 대화창4)</em> — 미인증 회원 상세의 「본인인증」 묶음에 <strong>[인증 완료로 처리]</strong> → 확인 모달(&quot;이 회원을 본인인증 완료로 바꿉니다. 적립대기 NP가 바로 지급되고, 고객에게 알림이 갑니다. 되돌리는 기능은 없어요.&quot;) → 처리 후 상세를 다시 연다. <strong>해제 기능은 두지 않는다</strong> (PO 2026-10-28)</li>\n<li><strong>적립대기 모아보기</strong> <em>(10-28 추가 — 대화창4)</em> — 회원 목록 찾기에 「적립대기: 전체 / 있음」 · 목록 위 한 줄 「적립대기 회원 N명 · 합계 NP」 (같은 기준: 미인증 + 보유 1P 이상)</li>\n</ul>\n<hr />\n<h3 id=\"s5-5\">5-5. 같은 명의 계정에서 옮겨 옴 <em>(10-28 통합 폐지 — 대화창4)</em></h3>\n<blockquote>\n<p>계정 통합은 하지 않는다(회원 정책 3-2 · <code>[PO 결정 2026-10-28]</code>). 대신 같은 명의의 두 번째 계정이 본인인증 때 걸리면, 그 계정의 적립대기·예약을 이미 인증된 계정으로 <strong>옮기고 두 번째 계정을 삭제</strong>한다(회원 정책 3-3). 삭제된 계정을 다시 찾을 단서가 어드민에만 남는다.</p>\n</blockquote>\n<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>목록 — 이메일 칸</strong></td>\n  <td>옮겨 받은 회원은 이메일 옆에 <strong>「옮겨 옴 N」</strong> 배지, 그 아래 <strong>옮긴 뒤 삭제된 계정 이메일</strong>(↳ 표시 · 이 주소로도 검색)</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td><strong>상세 — 「같은 명의 계정에서 옮겨 옴 N건」</strong></td>\n  <td>일시 · 「같은 명의 — 적립대기 옮김」 · <strong>옮긴 계정(삭제됨 — 이메일·회원번호)</strong> · 그 계정 가입일 · <strong>옮긴 적립대기</strong></td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td><strong>포인트 원장</strong></td>\n  <td>옮긴 적립대기는 받는 계정에서 <strong>원래 유형 그대로</strong>(예약 적립·관리자 지급 등) 지급된다 — 별도 「이관」 줄 없음</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td><strong>회원번호 매핑</strong></td>\n  <td>옮긴 기록이 「삭제된 회원번호 → 받은 회원번호」 매핑이다 — 예약 정산이 옛 회원번호로 오면 이 기록으로 찾는다(회원 R-M8)</td>\n  <td><code>[PO 결정 2026-10-28]</code></td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><code>미결</code> — 매핑 조회 화면은 넣지 않았다(R-M8 구현 때).</p>\n</blockquote>"}, "s5-1": {"t": "5-1. 목록", "h": "<p>열: 선택 · <strong>회원ID(이메일)</strong> · 이름 · 본인인증 · 추천코드 · 추천한 친구 · 보유 포인트 · 가입일 · 관리</p>\n<ul>\n<li>찾기: <strong>가입일</strong>(달력) · 본인인증(전체/완료/미완료) · 검색어(이메일·이름·추천코드)</li>\n<li>회원 ID는 <strong>이메일 주소</strong>다. 별도 아이디를 두지 않는다</li>\n<li><strong>보유 포인트 — 적립대기 표시</strong> <em>(v0.2)</em>: <strong>미인증 회원</strong>인데 (원장 잔액 + 적립대기)가 <strong>1 이상</strong>이면 그 합계를 보여주고 오른쪽에 작은 <strong>「적립대기」</strong> 를 붙인다 (예: 「500P 적립대기」). 인증 회원·0P 는 원장 잔액 그대로</li>\n</ul>\n<blockquote>\n<p><strong>적립대기</strong> — 로그인했지만 <strong>본인인증 전</strong>인 회원에게 생긴 적립(예약 적립 · 친구 추천 · 관리자 지급). 원장에 넣지 않고 기다렸다가 <strong>본인인증하는 순간 한꺼번에 지급</strong>한다(기한 없음 · 적립일 = 지급일). 상세는 참여형적립 기능정책서 1-6절</p>\n</blockquote>"}, "s5-2": {"t": "5-2. 상세", "h": "<p>좌우 두 단으로 <strong>기본 정보</strong>와 <strong>포인트 내역</strong>을 함께 본다.</p>\n<ul>\n<li><strong>미인증 회원</strong> <em>(v0.2)</em> — 포인트 요약의 「사용 가능」 대신 <strong>「보유 NP 적립대기」</strong> 를 보여주고, 그 아래 안내\n<strong>「본인인증 전이에요. 아래 포인트는 고객 화면에 보이지 않고, 본인인증을 하면 그때 지급돼요.」</strong> 와\n내역 칩(<strong>예약 · 친구 추천 · 관리자 지급·회수 · 이전에 쌓인 포인트</strong> — 각 금액·건수)을 둔다</li>\n</ul>"}, "s5-3": {"t": "5-3. 포인트 수동 지급·회수", "h": "<ul>\n<li>목록에서 <strong>회원을 골라 한 번에</strong> 처리할 수 있다</li>\n<li><strong>금액과 사유</strong>를 적어야 한다. 사유는 원장에 그대로 남는다</li>\n<li>처리하면 <strong>원장에 한 줄로 쌓이고</strong>, 관리자 로그에도 남는다(<code>point_grant</code>)</li>\n<li><strong>미인증 회원</strong> <em>(v0.2 · PO 확정 2026-10-27)</em> — 지급·회수할 수 있다. 다만 <strong>적립대기로 들어가고</strong>, 본인인증을 해야 고객 화면에 보이고 실제로 적립된다<ul>\n<li>미인증 회원에게는 지급·회수 <strong>알림을 보내지 않는다</strong> (금액이 드러나므로). 인증으로 지급될 때 「적립대기 포인트 +NP」 1건</li>\n<li>회수는 <strong>(원장 잔액 + 적립대기) 안에서만</strong> — 넘으면 「회수할 포인트가 모자라요 (적립대기 포함)」</li>\n<li>결과 안내: 단건 「본인인증 전 회원이라 적립대기로 넣었어요 · 인증하면 지급돼요」 / 일괄 「N명 처리 완료 · 그중 N명은 본인인증 전이라 적립대기」</li>\n</ul>\n</li>\n</ul>\n<blockquote>\n<p><code>미결</code> — <strong>권한·한도·처리자 기록</strong>이 정해지지 않았다.\n지금은 누구나 금액 제한 없이 지급·회수할 수 있다. (2-2 참조)</p>\n</blockquote>"}, "s5-4": {"t": "5-4. 본인인증 처리 (v0.2 신설)", "h": "<ul>\n<li>회원 상세에서 관리자가 본인인증 상태를 <strong>완료</strong>로 바꿀 수 있다 (시연용)</li>\n<li>완료로 바꾸면 <strong>고객이 직접 인증한 것과 같이 적립대기를 지급</strong>한다 · 관리자 로그에 「본인인증 완료 · 적립대기 NP 지급」</li>\n<li><strong>화면</strong> <em>(10-28 추가 — 대화창4)</em> — 미인증 회원 상세의 「본인인증」 묶음에 <strong>[인증 완료로 처리]</strong> → 확인 모달(&quot;이 회원을 본인인증 완료로 바꿉니다. 적립대기 NP가 바로 지급되고, 고객에게 알림이 갑니다. 되돌리는 기능은 없어요.&quot;) → 처리 후 상세를 다시 연다. <strong>해제 기능은 두지 않는다</strong> (PO 2026-10-28)</li>\n<li><strong>적립대기 모아보기</strong> <em>(10-28 추가 — 대화창4)</em> — 회원 목록 찾기에 「적립대기: 전체 / 있음」 · 목록 위 한 줄 「적립대기 회원 N명 · 합계 NP」 (같은 기준: 미인증 + 보유 1P 이상)</li>\n</ul>\n<hr />"}, "s5-5": {"t": "5-5. 같은 명의 계정에서 옮겨 옴 (10-28 통합 폐지 — 대화창4)", "h": "<blockquote>\n<p>계정 통합은 하지 않는다(회원 정책 3-2 · <code>[PO 결정 2026-10-28]</code>). 대신 같은 명의의 두 번째 계정이 본인인증 때 걸리면, 그 계정의 적립대기·예약을 이미 인증된 계정으로 <strong>옮기고 두 번째 계정을 삭제</strong>한다(회원 정책 3-3). 삭제된 계정을 다시 찾을 단서가 어드민에만 남는다.</p>\n</blockquote>\n<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>목록 — 이메일 칸</strong></td>\n  <td>옮겨 받은 회원은 이메일 옆에 <strong>「옮겨 옴 N」</strong> 배지, 그 아래 <strong>옮긴 뒤 삭제된 계정 이메일</strong>(↳ 표시 · 이 주소로도 검색)</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td><strong>상세 — 「같은 명의 계정에서 옮겨 옴 N건」</strong></td>\n  <td>일시 · 「같은 명의 — 적립대기 옮김」 · <strong>옮긴 계정(삭제됨 — 이메일·회원번호)</strong> · 그 계정 가입일 · <strong>옮긴 적립대기</strong></td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td><strong>포인트 원장</strong></td>\n  <td>옮긴 적립대기는 받는 계정에서 <strong>원래 유형 그대로</strong>(예약 적립·관리자 지급 등) 지급된다 — 별도 「이관」 줄 없음</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td><strong>회원번호 매핑</strong></td>\n  <td>옮긴 기록이 「삭제된 회원번호 → 받은 회원번호」 매핑이다 — 예약 정산이 옛 회원번호로 오면 이 기록으로 찾는다(회원 R-M8)</td>\n  <td><code>[PO 결정 2026-10-28]</code></td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><code>미결</code> — 매핑 조회 화면은 넣지 않았다(R-M8 구현 때).</p>\n</blockquote>"}, "s6": {"t": "제6조 (전체 포인트 내역 — 원장)", "h": "<h3 id=\"s6-1\">6-1. 원칙 — 잔액을 저장하지 않는다</h3>\n<ul>\n<li>포인트가 움직인 <strong>모든 사건이 한 줄씩</strong> 쌓인다</li>\n<li>잔액은 <strong>그 줄들을 더한 결과</strong>다</li>\n<li>이 화면은 <strong>보기만 하고 고치지 않는다</strong></li>\n</ul>\n<blockquote>\n<p><strong>왜</strong> — 기록을 고칠 수 있으면 기록이 아니다.\n포인트를 바꿔야 하면 <strong>회원 상세에서 사유를 적어 처리</strong>하고,\n그 행위 자체가 또 한 줄로 쌓인다. <strong>지우는 길을 만들지 않는 것</strong>이 핵심이다.</p>\n</blockquote>\n<h3 id=\"s6-2\">6-2. 열</h3>\n<p><code>#</code> · 유형 · 회원 · 증감 · 잔액 · 내용 · 소멸예정 · 일시</p>\n<h3 id=\"s6-3\">6-3. 포인트 유형</h3>\n<table>\n<thead>\n<tr>\n  <th>유형</th>\n  <th>뜻</th>\n  <th style=\"text-align:center\">증감</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><code>attend</code></td>\n  <td>출석체크</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>quiz</code></td>\n  <td>퀴즈</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>offer</code></td>\n  <td>혜택(오퍼월) 참여</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>booking</code></td>\n  <td>숙소 예약 기본 적립</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>booking_draw</code></td>\n  <td>예약 뽑기</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>invite_out</code></td>\n  <td>친구 추천 — 추천한 사람</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>invite_in</code></td>\n  <td>친구 추천 — 가입한 사람</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>shop</code></td>\n  <td>픽샵 구매</td>\n  <td style=\"text-align:center\">−</td>\n</tr>\n<tr>\n  <td><code>shop_cancel</code></td>\n  <td>픽샵 구매 취소 환불</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>withdraw</code></td>\n  <td>출금 신청 차감</td>\n  <td style=\"text-align:center\">−</td>\n</tr>\n<tr>\n  <td><code>cancel_refund</code></td>\n  <td>출금 반려 환불</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n</tbody>\n</table>\n<h3 id=\"s6-4\">6-4. 찾기</h3>\n<ul>\n<li>유형 칩(출석체크·숙소예약·혜택참여·퀴즈·친구추천 …) — <strong>칩마다 건수 표시</strong></li>\n<li><strong>날짜 기준</strong>: 적립일 / 소멸예정일 중 선택 → 기간(달력)</li>\n<li>검색어: 회원·내용</li>\n</ul>\n<hr />"}, "s6-1": {"t": "6-1. 원칙 — 잔액을 저장하지 않는다", "h": "<ul>\n<li>포인트가 움직인 <strong>모든 사건이 한 줄씩</strong> 쌓인다</li>\n<li>잔액은 <strong>그 줄들을 더한 결과</strong>다</li>\n<li>이 화면은 <strong>보기만 하고 고치지 않는다</strong></li>\n</ul>\n<blockquote>\n<p><strong>왜</strong> — 기록을 고칠 수 있으면 기록이 아니다.\n포인트를 바꿔야 하면 <strong>회원 상세에서 사유를 적어 처리</strong>하고,\n그 행위 자체가 또 한 줄로 쌓인다. <strong>지우는 길을 만들지 않는 것</strong>이 핵심이다.</p>\n</blockquote>"}, "s6-2": {"t": "6-2. 열", "h": "<p><code>#</code> · 유형 · 회원 · 증감 · 잔액 · 내용 · 소멸예정 · 일시</p>"}, "s6-3": {"t": "6-3. 포인트 유형", "h": "<table>\n<thead>\n<tr>\n  <th>유형</th>\n  <th>뜻</th>\n  <th style=\"text-align:center\">증감</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><code>attend</code></td>\n  <td>출석체크</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>quiz</code></td>\n  <td>퀴즈</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>offer</code></td>\n  <td>혜택(오퍼월) 참여</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>booking</code></td>\n  <td>숙소 예약 기본 적립</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>booking_draw</code></td>\n  <td>예약 뽑기</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>invite_out</code></td>\n  <td>친구 추천 — 추천한 사람</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>invite_in</code></td>\n  <td>친구 추천 — 가입한 사람</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>shop</code></td>\n  <td>픽샵 구매</td>\n  <td style=\"text-align:center\">−</td>\n</tr>\n<tr>\n  <td><code>shop_cancel</code></td>\n  <td>픽샵 구매 취소 환불</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n<tr>\n  <td><code>withdraw</code></td>\n  <td>출금 신청 차감</td>\n  <td style=\"text-align:center\">−</td>\n</tr>\n<tr>\n  <td><code>cancel_refund</code></td>\n  <td>출금 반려 환불</td>\n  <td style=\"text-align:center\">+</td>\n</tr>\n</tbody>\n</table>"}, "s6-4": {"t": "6-4. 찾기", "h": "<ul>\n<li>유형 칩(출석체크·숙소예약·혜택참여·퀴즈·친구추천 …) — <strong>칩마다 건수 표시</strong></li>\n<li><strong>날짜 기준</strong>: 적립일 / 소멸예정일 중 선택 → 기간(달력)</li>\n<li>검색어: 회원·내용</li>\n</ul>\n<hr />"}, "s7": {"t": "제7조 (출금 신청)", "h": "<h3 id=\"s7-1\">7-1. 흐름</h3>\n<ol>\n<li>고객이 신청하면 <strong>포인트가 즉시 차감</strong>된다 (<code>withdraw</code>)</li>\n<li>운영자가 회원·금액·계좌를 확인한다</li>\n<li>실제로 송금한 뒤 <strong>[지급하기]</strong> 를 누른다</li>\n<li>문제가 있으면 <strong>[반려]</strong> 를 누른다 → <strong>차감한 포인트가 바로 환불</strong>된다 (<code>cancel_refund</code>)</li>\n</ol>\n<ul>\n<li><strong>사전 승인 단계는 없다.</strong> 처리대기 건을 [지급하기] 또는 [반려] 둘 중 하나로 끝낸다</li>\n<li>지급·반려 모두 <strong>고객에게 알림이 간다</strong></li>\n</ul>\n<h3 id=\"s7-2\">7-2. 반려 사유 (필수)</h3>\n<table>\n<thead>\n<tr>\n  <th>사유</th>\n  <th>성격</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>고객 요청으로 취소</td>\n  <td>고객 사정</td>\n</tr>\n<tr>\n  <td>예금주 이름이 계좌와 달라요</td>\n  <td>운영자 거절</td>\n</tr>\n<tr>\n  <td>계좌번호를 다시 확인해 주세요</td>\n  <td>운영자 거절</td>\n</tr>\n<tr>\n  <td>본인 명의 계좌가 아니에요</td>\n  <td>운영자 거절</td>\n</tr>\n<tr>\n  <td>(직접 입력)</td>\n  <td>—</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>고른 사유는 <strong>목록에 남고 고객에게 그대로 전달</strong>된다</li>\n</ul>\n<blockquote>\n<p><strong>왜 사유를 고르게 하나</strong> — <strong>고객이 취소를 요청한 것</strong>과\n<strong>운영자가 거절한 것</strong>은 성격이 다르다. 섞어 두면 나중에\n「반려가 많다」가 무슨 뜻인지 읽히지 않는다. (PO 지적 · 2026-10-12)</p>\n</blockquote>\n<h3 id=\"s7-3\">7-3. 열과 찾기</h3>\n<p>열: 상태 · 회원 · 금액 · 입금 계좌 · 예금주 · 신청일시 · 지급일시 · 처리</p>\n<ul>\n<li>날짜 기준: <strong>신청일 / 지급일</strong> → 기간(달력)</li>\n<li>입금 은행(목록에 실제로 있는 은행만) · 처리 상태(처리대기/지급완료/반려) · 검색어</li>\n</ul>\n<h3 id=\"s7-4\">7-4. 한도 (설정값)</h3>\n<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>현재 값</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>최소 신청액</td>\n  <td>10,000P</td>\n</tr>\n<tr>\n  <td>1회 한도</td>\n  <td>100,000P</td>\n</tr>\n<tr>\n  <td>신청 단위</td>\n  <td>1,000P</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><code>미결</code> — <strong>월 한도</strong>는 고객 화면에만 있고 <strong>서버가 검증하지 않는다.</strong>\n출금 수수료 부담 주체도 정해지지 않았다.</p>\n</blockquote>\n<hr />"}, "s7-1": {"t": "7-1. 흐름", "h": "<ol>\n<li>고객이 신청하면 <strong>포인트가 즉시 차감</strong>된다 (<code>withdraw</code>)</li>\n<li>운영자가 회원·금액·계좌를 확인한다</li>\n<li>실제로 송금한 뒤 <strong>[지급하기]</strong> 를 누른다</li>\n<li>문제가 있으면 <strong>[반려]</strong> 를 누른다 → <strong>차감한 포인트가 바로 환불</strong>된다 (<code>cancel_refund</code>)</li>\n</ol>\n<ul>\n<li><strong>사전 승인 단계는 없다.</strong> 처리대기 건을 [지급하기] 또는 [반려] 둘 중 하나로 끝낸다</li>\n<li>지급·반려 모두 <strong>고객에게 알림이 간다</strong></li>\n</ul>"}, "s7-2": {"t": "7-2. 반려 사유 (필수)", "h": "<table>\n<thead>\n<tr>\n  <th>사유</th>\n  <th>성격</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>고객 요청으로 취소</td>\n  <td>고객 사정</td>\n</tr>\n<tr>\n  <td>예금주 이름이 계좌와 달라요</td>\n  <td>운영자 거절</td>\n</tr>\n<tr>\n  <td>계좌번호를 다시 확인해 주세요</td>\n  <td>운영자 거절</td>\n</tr>\n<tr>\n  <td>본인 명의 계좌가 아니에요</td>\n  <td>운영자 거절</td>\n</tr>\n<tr>\n  <td>(직접 입력)</td>\n  <td>—</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>고른 사유는 <strong>목록에 남고 고객에게 그대로 전달</strong>된다</li>\n</ul>\n<blockquote>\n<p><strong>왜 사유를 고르게 하나</strong> — <strong>고객이 취소를 요청한 것</strong>과\n<strong>운영자가 거절한 것</strong>은 성격이 다르다. 섞어 두면 나중에\n「반려가 많다」가 무슨 뜻인지 읽히지 않는다. (PO 지적 · 2026-10-12)</p>\n</blockquote>"}, "s7-3": {"t": "7-3. 열과 찾기", "h": "<p>열: 상태 · 회원 · 금액 · 입금 계좌 · 예금주 · 신청일시 · 지급일시 · 처리</p>\n<ul>\n<li>날짜 기준: <strong>신청일 / 지급일</strong> → 기간(달력)</li>\n<li>입금 은행(목록에 실제로 있는 은행만) · 처리 상태(처리대기/지급완료/반려) · 검색어</li>\n</ul>"}, "s7-4": {"t": "7-4. 한도 (설정값)", "h": "<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>현재 값</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>최소 신청액</td>\n  <td>10,000P</td>\n</tr>\n<tr>\n  <td>1회 한도</td>\n  <td>100,000P</td>\n</tr>\n<tr>\n  <td>신청 단위</td>\n  <td>1,000P</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><code>미결</code> — <strong>월 한도</strong>는 고객 화면에만 있고 <strong>서버가 검증하지 않는다.</strong>\n출금 수수료 부담 주체도 정해지지 않았다.</p>\n</blockquote>\n<hr />"}, "s8": {"t": "제8조 (픽샵 구매내역)", "h": "<h3 id=\"s8-1\">8-1. 원칙 — 자금 이동이 없다</h3>\n<p>포인트로 쿠폰을 바꾸는 것이라 <strong>승인 절차를 두지 않는다.</strong>\n구매 즉시 <strong>쿠폰이 자동 발행</strong>된다.</p>\n<h3 id=\"s8-2\">8-2. 운영자가 하는 일</h3>\n<ul>\n<li><strong>쿠폰번호 재발행</strong> — 고객의 쿠폰번호 분실이 실제로 잦다</li>\n<li>취소 건 확인 — 취소하면 <strong>포인트 환불 + 재고 복구</strong></li>\n<li>고객이 쿠폰을 쓰고 [사용 처리]를 누르면 <strong>사용완료</strong>로 바뀐다</li>\n</ul>\n<h3 id=\"s8-3\">8-3. 상태</h3>\n<p><code>구매완료</code> · <code>사용완료</code> · <code>구매취소</code> · <code>발행실패</code></p>\n<h3 id=\"s8-4\">8-4. 열</h3>\n<p><code>#</code> · 상태 · 회원 · 상품 · 사용 포인트 · 쿠폰번호 · 구매일시 · 사용·취소일시 · 관리</p>\n<blockquote>\n<p><code>미결</code> — <strong>쿠폰 발행 업체가 정해지지 않았다.</strong>\n현재 쿠폰번호는 <strong>자사에서 만들어 보여주는 것</strong>이다.</p>\n</blockquote>\n<hr />"}, "s8-1": {"t": "8-1. 원칙 — 자금 이동이 없다", "h": "<p>포인트로 쿠폰을 바꾸는 것이라 <strong>승인 절차를 두지 않는다.</strong>\n구매 즉시 <strong>쿠폰이 자동 발행</strong>된다.</p>"}, "s8-2": {"t": "8-2. 운영자가 하는 일", "h": "<ul>\n<li><strong>쿠폰번호 재발행</strong> — 고객의 쿠폰번호 분실이 실제로 잦다</li>\n<li>취소 건 확인 — 취소하면 <strong>포인트 환불 + 재고 복구</strong></li>\n<li>고객이 쿠폰을 쓰고 [사용 처리]를 누르면 <strong>사용완료</strong>로 바뀐다</li>\n</ul>"}, "s8-3": {"t": "8-3. 상태", "h": "<p><code>구매완료</code> · <code>사용완료</code> · <code>구매취소</code> · <code>발행실패</code></p>"}, "s8-4": {"t": "8-4. 열", "h": "<p><code>#</code> · 상태 · 회원 · 상품 · 사용 포인트 · 쿠폰번호 · 구매일시 · 사용·취소일시 · 관리</p>\n<blockquote>\n<p><code>미결</code> — <strong>쿠폰 발행 업체가 정해지지 않았다.</strong>\n현재 쿠폰번호는 <strong>자사에서 만들어 보여주는 것</strong>이다.</p>\n</blockquote>\n<hr />"}, "s9": {"t": "제9조 (예약 적립)", "h": "<h3 id=\"s9-1\">9-1. 구조</h3>\n<p>숙소 예약으로 예약처가 지급하는 재원을 <strong>기본 적립</strong>과 <strong>뽑기</strong> 둘로 나눈다.</p>\n<table>\n<thead>\n<tr>\n  <th>몫</th>\n  <th>현재 값</th>\n  <th>지급 시점</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>기본 적립</td>\n  <td>예약금액의 <strong>1%</strong> (<code>draw_base_rate</code>)</td>\n  <td>예약 즉시</td>\n</tr>\n<tr>\n  <td>뽑기 몫</td>\n  <td>나머지</td>\n  <td>고객이 뽑기를 해야 지급</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>왜 나누나</strong> — 예약 적립은 <strong>자사 비용이 아니라 예약처가 주는 재원</strong>이다.\n뽑지 않은 금액은 <strong>비용 절감인 동시에 고객이 받지 못한 금액</strong>이다.\n이 수치가 계속 늘면 <strong>뽑기 안내가 부족하다는 뜻</strong>이다.</p>\n</blockquote>\n<h3 id=\"s9-2\">9-2. 열</h3>\n<p><code>#</code> · 회원 · 호텔 · OTA · 예약금액 · 요율 · 기본적립 · 뽑기 · 총 적립 · <strong>체크인/체크아웃</strong> · 적립일시</p>\n<h3 id=\"s9-3\">9-3. 숙박일을 함께 보는 이유</h3>\n<p>적립이 확정되는 시점은 <strong>예약한 날이 아니라 숙박을 마친 뒤</strong>다.\n예약처가 보내 주는 자료에도 체크인·체크아웃 날짜가 담겨 있어 <strong>대조 기준</strong>이 된다.</p>\n<h3 id=\"s9-4\">9-4. 찾기</h3>\n<ul>\n<li>날짜 기준: <strong>숙박일 / 적립일</strong> → 기간(달력)</li>\n<li>뽑기: 전체 / 미수령 · 검색어</li>\n</ul>\n<h3 id=\"s9-5\">9-5. 상태</h3>\n<p><del><code>적립완료</code> / <code>취소</code> 둘로만 구분한다. 「적립예정」 단계를 두지 않는다.</del> → <strong><code>적립예정</code> → <code>적립완료</code> / <code>취소</code></strong> <em>(10-28 추가 — 대화창4)</em></p>\n<ul>\n<li><p><strong><code>적립예정</code></strong> — 예약은 기록됐고 <strong>적립예정일(체크아웃 + 7일)</strong> 을 기다리는 상태. 「총 적립」 칸에 「적립예정」 배지 + 「적립예정일 YYYY-MM-DD」, 뽑기 칸은 「적립 후」, 위쪽 합계에서 <strong>빠진다</strong> (포인트 정책 v0.2 3절 · 프로토 #37)</p>\n</li>\n<li><p>적립예정일이 지나면 서버가 확정한다 — 인증 회원은 <code>적립완료</code> + 알림, 미인증 회원은 <code>적립대기</code>. 「적립일시」 칸 = 확정한 시각(뽑기 기한의 기준)</p>\n</li>\n<li><p><strong>[지금 확정]</strong> (시연용) — 적립예정 행에 버튼. 적립예정일을 기다리지 않고 바로 확정한다 · 로그 「예약 적립 확정」</p>\n</li>\n<li><p>[+ 예약 적립 만들기]도 <strong>적립예정</strong>으로 만든다 (결과 「적립예정으로 만들었어요 · 적립예정일 …」)</p>\n</li>\n<li><p>예외 — <strong><code>적립대기</code></strong> <em>(v0.2)</em>: 본인인증 전 회원의 예약. 예약은 기록하되 포인트는 지급 전이다.\n「총 적립」 칸에 <strong>「적립대기」 배지 + 「본인인증 전 · NP」</strong>, 위쪽 합계에서는 <strong>빠진다</strong>. 인증하면 <code>적립완료</code> 로 바뀌고 뽑기가 열린다</p>\n</li>\n</ul>\n<blockquote>\n<p><del><code>미결</code></del> <strong>해소 2026-10-27</strong> — 뽑기 가능 기간 <strong>적립완료일 + 30일</strong>(<code>draw_expire_days=30</code>) · 포인트 정책서 v0.2 4절.\n정책상 30일 예정이나 확정되지 않았다.</p>\n</blockquote>\n<blockquote>\n<p>실제 운영에서는 <strong>호텔스컴바인이 예약 결과를 알려준다.</strong>\n시연에서는 고객이 아웃링크 화면에서 [예약 완료 처리]를 눌러 만든다.\n실연동 시에는 <strong>확정까지 수개월</strong>이 걸리고 <strong>누락되는 건도 있다.</strong></p>\n</blockquote>\n<hr />"}, "s9-1": {"t": "9-1. 구조", "h": "<p>숙소 예약으로 예약처가 지급하는 재원을 <strong>기본 적립</strong>과 <strong>뽑기</strong> 둘로 나눈다.</p>\n<table>\n<thead>\n<tr>\n  <th>몫</th>\n  <th>현재 값</th>\n  <th>지급 시점</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>기본 적립</td>\n  <td>예약금액의 <strong>1%</strong> (<code>draw_base_rate</code>)</td>\n  <td>예약 즉시</td>\n</tr>\n<tr>\n  <td>뽑기 몫</td>\n  <td>나머지</td>\n  <td>고객이 뽑기를 해야 지급</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>왜 나누나</strong> — 예약 적립은 <strong>자사 비용이 아니라 예약처가 주는 재원</strong>이다.\n뽑지 않은 금액은 <strong>비용 절감인 동시에 고객이 받지 못한 금액</strong>이다.\n이 수치가 계속 늘면 <strong>뽑기 안내가 부족하다는 뜻</strong>이다.</p>\n</blockquote>"}, "s9-2": {"t": "9-2. 열", "h": "<p><code>#</code> · 회원 · 호텔 · OTA · 예약금액 · 요율 · 기본적립 · 뽑기 · 총 적립 · <strong>체크인/체크아웃</strong> · 적립일시</p>"}, "s9-3": {"t": "9-3. 숙박일을 함께 보는 이유", "h": "<p>적립이 확정되는 시점은 <strong>예약한 날이 아니라 숙박을 마친 뒤</strong>다.\n예약처가 보내 주는 자료에도 체크인·체크아웃 날짜가 담겨 있어 <strong>대조 기준</strong>이 된다.</p>"}, "s9-4": {"t": "9-4. 찾기", "h": "<ul>\n<li>날짜 기준: <strong>숙박일 / 적립일</strong> → 기간(달력)</li>\n<li>뽑기: 전체 / 미수령 · 검색어</li>\n</ul>"}, "s9-5": {"t": "9-5. 상태", "h": "<p><del><code>적립완료</code> / <code>취소</code> 둘로만 구분한다. 「적립예정」 단계를 두지 않는다.</del> → <strong><code>적립예정</code> → <code>적립완료</code> / <code>취소</code></strong> <em>(10-28 추가 — 대화창4)</em></p>\n<ul>\n<li><p><strong><code>적립예정</code></strong> — 예약은 기록됐고 <strong>적립예정일(체크아웃 + 7일)</strong> 을 기다리는 상태. 「총 적립」 칸에 「적립예정」 배지 + 「적립예정일 YYYY-MM-DD」, 뽑기 칸은 「적립 후」, 위쪽 합계에서 <strong>빠진다</strong> (포인트 정책 v0.2 3절 · 프로토 #37)</p>\n</li>\n<li><p>적립예정일이 지나면 서버가 확정한다 — 인증 회원은 <code>적립완료</code> + 알림, 미인증 회원은 <code>적립대기</code>. 「적립일시」 칸 = 확정한 시각(뽑기 기한의 기준)</p>\n</li>\n<li><p><strong>[지금 확정]</strong> (시연용) — 적립예정 행에 버튼. 적립예정일을 기다리지 않고 바로 확정한다 · 로그 「예약 적립 확정」</p>\n</li>\n<li><p>[+ 예약 적립 만들기]도 <strong>적립예정</strong>으로 만든다 (결과 「적립예정으로 만들었어요 · 적립예정일 …」)</p>\n</li>\n<li><p>예외 — <strong><code>적립대기</code></strong> <em>(v0.2)</em>: 본인인증 전 회원의 예약. 예약은 기록하되 포인트는 지급 전이다.\n「총 적립」 칸에 <strong>「적립대기」 배지 + 「본인인증 전 · NP」</strong>, 위쪽 합계에서는 <strong>빠진다</strong>. 인증하면 <code>적립완료</code> 로 바뀌고 뽑기가 열린다</p>\n</li>\n</ul>\n<blockquote>\n<p><del><code>미결</code></del> <strong>해소 2026-10-27</strong> — 뽑기 가능 기간 <strong>적립완료일 + 30일</strong>(<code>draw_expire_days=30</code>) · 포인트 정책서 v0.2 4절.\n정책상 30일 예정이나 확정되지 않았다.</p>\n</blockquote>\n<blockquote>\n<p>실제 운영에서는 <strong>호텔스컴바인이 예약 결과를 알려준다.</strong>\n시연에서는 고객이 아웃링크 화면에서 [예약 완료 처리]를 눌러 만든다.\n실연동 시에는 <strong>확정까지 수개월</strong>이 걸리고 <strong>누락되는 건도 있다.</strong></p>\n</blockquote>\n<hr />"}, "s10": {"t": "제10조 (적립 운영 — 혜택 · 퀴즈 · 광고주)", "h": "<h3 id=\"s10-1\">10-1. 혜택(오퍼월)</h3>\n<p>열: 선택 · 노출 · 썸네일 · 제목 · 광고주 · 분류 · 적립 · 체류 · 노출기간 · 버튼명 · 아웃링크 · 참여수 · 관리</p>\n<ul>\n<li>고객이 버튼을 누르면 <strong>광고주 페이지로 이동</strong>하고, <strong>체류 시간을 채우면 적립</strong>된다</li>\n<li>여러 건을 골라 <strong>일괄 수정</strong>할 수 있다</li>\n</ul>\n<h3 id=\"s10-2\">10-2. 퀴즈</h3>\n<p>열: 노출 · 문항 · 정답 · 해설 · 광고 · <strong>출제여부</strong> · 관리</p>\n<p><strong>출제여부 3단계</strong> (2026-10-12 확정)</p>\n<table>\n<thead>\n<tr>\n  <th>단계</th>\n  <th>뜻</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>대기</strong></td>\n  <td>노출 ON · 아직 한 번도 안 나감</td>\n</tr>\n<tr>\n  <td><strong>출제중</strong></td>\n  <td>노출 ON · 나간 적 있음</td>\n</tr>\n<tr>\n  <td><strong>출제완료</strong></td>\n  <td>노출 OFF · 더 이상 출제하지 않음</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>왜 셋으로 나눴나</strong> — 켜짐/꺼짐 두 가지로는 <strong>「한 번이라도 나갔나」</strong>밖에 알 수 없다.\n운영자가 알고 싶은 것은 <strong>새 문항이 얼마나 남았는지</strong>와\n<strong>지금 도는 문항이 몇 개인지</strong>다.</p>\n</blockquote>\n<ul>\n<li>매일 켜져 있는 문항 중 <strong>3개를 무작위</strong>로 뽑는다 (<code>quiz_count</code>)</li>\n<li>이미 푼 문항은 <strong>기간 없이</strong> 제외된다. 설정 <strong>「푼 문제 다시 출제 허용」</strong> 을 켜면 제외를 풀고 모든 회원에게 다시 출제한다 <em>(2026-10-26 PO 확정 · v0.2 구현 완료 — <code>quiz_allow_repeat</code>)</em></li>\n<li>출제 근거는 <strong>선택 입력</strong> — 엑셀 근거 칸은 비어도 등록, 문항 창에는 근거 칸 없음 <em>(2026-10-26 PO 확정)</em></li>\n<li>문항마다 <strong>광고 링크</strong>를 붙일 수 있다 — 해설 아래 버튼으로 나온다. <strong>등록할 때도 광고가 함께 저장</strong>된다 <em>(v0.2)</em></li>\n<li>광고를 <strong>「사용」으로 두면 링크가 있어야</strong> 저장된다 — 없으면 「광고를 사용하려면 광고 링크를 입력해 주세요」 <em>(v0.2)</em></li>\n<li><strong>같은 문장의 문항은 등록·수정할 수 없다</strong> — 「이미 등록된 문항이에요」 <em>(v0.2 · 엑셀 등록은 이미 건너뛰고 있었음)</em></li>\n<li>문항 창의 해설 칸 이름 = <strong>「해설 (정답 공개 후 항상 보여줍니다)」</strong> — 고객 화면은 정답·오답 모두 해설을 보여준다 <em>(v0.2)</em></li>\n<li><strong>엑셀 일괄 등록</strong> 지원</li>\n</ul>\n<blockquote>\n<p><code>미결</code> — <strong>출제 근거를 무엇으로 담보할지</strong>. 근거 URL 입력란은 v0.6에서 없앴다.\n문항별 광고 표기 의무도 확인이 필요하다.</p>\n</blockquote>\n<h3 id=\"s10-3\">10-3. 광고주</h3>\n<p>열: 사용 · 광고주명 · 사업자번호 · 담당자 · 정산방식 · 광고수 · 메모 · 관리</p>\n<ul>\n<li><strong>여기 등록된 광고주만</strong> 광고를 올릴 수 있다</li>\n</ul>\n<blockquote>\n<p><code>미결</code> — <strong>정산·과금(CPC/CPA 요율, 정산 주기, 세금계산서)</strong> 이 정해지지 않아\n이번 버전에서는 <strong>등록만</strong> 한다.</p>\n</blockquote>\n<hr />"}, "s10-1": {"t": "10-1. 혜택(오퍼월)", "h": "<p>열: 선택 · 노출 · 썸네일 · 제목 · 광고주 · 분류 · 적립 · 체류 · 노출기간 · 버튼명 · 아웃링크 · 참여수 · 관리</p>\n<ul>\n<li>고객이 버튼을 누르면 <strong>광고주 페이지로 이동</strong>하고, <strong>체류 시간을 채우면 적립</strong>된다</li>\n<li>여러 건을 골라 <strong>일괄 수정</strong>할 수 있다</li>\n</ul>"}, "s10-2": {"t": "10-2. 퀴즈", "h": "<p>열: 노출 · 문항 · 정답 · 해설 · 광고 · <strong>출제여부</strong> · 관리</p>\n<p><strong>출제여부 3단계</strong> (2026-10-12 확정)</p>\n<table>\n<thead>\n<tr>\n  <th>단계</th>\n  <th>뜻</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>대기</strong></td>\n  <td>노출 ON · 아직 한 번도 안 나감</td>\n</tr>\n<tr>\n  <td><strong>출제중</strong></td>\n  <td>노출 ON · 나간 적 있음</td>\n</tr>\n<tr>\n  <td><strong>출제완료</strong></td>\n  <td>노출 OFF · 더 이상 출제하지 않음</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>왜 셋으로 나눴나</strong> — 켜짐/꺼짐 두 가지로는 <strong>「한 번이라도 나갔나」</strong>밖에 알 수 없다.\n운영자가 알고 싶은 것은 <strong>새 문항이 얼마나 남았는지</strong>와\n<strong>지금 도는 문항이 몇 개인지</strong>다.</p>\n</blockquote>\n<ul>\n<li>매일 켜져 있는 문항 중 <strong>3개를 무작위</strong>로 뽑는다 (<code>quiz_count</code>)</li>\n<li>이미 푼 문항은 <strong>기간 없이</strong> 제외된다. 설정 <strong>「푼 문제 다시 출제 허용」</strong> 을 켜면 제외를 풀고 모든 회원에게 다시 출제한다 <em>(2026-10-26 PO 확정 · v0.2 구현 완료 — <code>quiz_allow_repeat</code>)</em></li>\n<li>출제 근거는 <strong>선택 입력</strong> — 엑셀 근거 칸은 비어도 등록, 문항 창에는 근거 칸 없음 <em>(2026-10-26 PO 확정)</em></li>\n<li>문항마다 <strong>광고 링크</strong>를 붙일 수 있다 — 해설 아래 버튼으로 나온다. <strong>등록할 때도 광고가 함께 저장</strong>된다 <em>(v0.2)</em></li>\n<li>광고를 <strong>「사용」으로 두면 링크가 있어야</strong> 저장된다 — 없으면 「광고를 사용하려면 광고 링크를 입력해 주세요」 <em>(v0.2)</em></li>\n<li><strong>같은 문장의 문항은 등록·수정할 수 없다</strong> — 「이미 등록된 문항이에요」 <em>(v0.2 · 엑셀 등록은 이미 건너뛰고 있었음)</em></li>\n<li>문항 창의 해설 칸 이름 = <strong>「해설 (정답 공개 후 항상 보여줍니다)」</strong> — 고객 화면은 정답·오답 모두 해설을 보여준다 <em>(v0.2)</em></li>\n<li><strong>엑셀 일괄 등록</strong> 지원</li>\n</ul>\n<blockquote>\n<p><code>미결</code> — <strong>출제 근거를 무엇으로 담보할지</strong>. 근거 URL 입력란은 v0.6에서 없앴다.\n문항별 광고 표기 의무도 확인이 필요하다.</p>\n</blockquote>"}, "s10-3": {"t": "10-3. 광고주", "h": "<p>열: 사용 · 광고주명 · 사업자번호 · 담당자 · 정산방식 · 광고수 · 메모 · 관리</p>\n<ul>\n<li><strong>여기 등록된 광고주만</strong> 광고를 올릴 수 있다</li>\n</ul>\n<blockquote>\n<p><code>미결</code> — <strong>정산·과금(CPC/CPA 요율, 정산 주기, 세금계산서)</strong> 이 정해지지 않아\n이번 버전에서는 <strong>등록만</strong> 한다.</p>\n</blockquote>\n<hr />"}, "s11": {"t": "제11조 (알림)", "h": "<h3 id=\"s11-1\">11-1. 발송</h3>\n<ul>\n<li>보낸 알림은 <strong>고객 앱 알림함에 쌓이고 배지가 올라간다</strong></li>\n<li>유형: <code>공지사항</code> / <code>마케팅</code> / <code>시스템(자동)</code></li>\n<li>열: 발송일시 · 유형 · 대상 · 내용 · 읽음</li>\n</ul>\n<h3 id=\"s11-2\">11-2. 미결</h3>\n<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>현재</th>\n  <th>정해야 할 것</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>휴대폰 푸시</td>\n  <td>없음 — <strong>앱을 켜 둔 동안에만</strong> 전달</td>\n  <td>포인트 소멸처럼 꼭 닿아야 할 알림의 전달 수단</td>\n</tr>\n<tr>\n  <td>예약 발송·세그먼트</td>\n  <td>없음</td>\n  <td>다음 버전</td>\n</tr>\n<tr>\n  <td>수신 동의 연동</td>\n  <td>없음</td>\n  <td><strong>광고성 알림은 동의자에게만</strong> 보내는 규칙</td>\n</tr>\n<tr>\n  <td>보관 기간</td>\n  <td>화면에는 「90일 보관」이나 <strong>지우는 기능이 없다</strong>(최근 100건 표시)</td>\n  <td>문구 수정 또는 삭제 기능</td>\n</tr>\n<tr>\n  <td>확인 주기</td>\n  <td><strong>5초마다</strong> 확인 (시연용)</td>\n  <td>회원 수만큼 서버 부담 — 주기 상향 또는 푸시 전환</td>\n</tr>\n</tbody>\n</table>\n<hr />"}, "s11-1": {"t": "11-1. 발송", "h": "<ul>\n<li>보낸 알림은 <strong>고객 앱 알림함에 쌓이고 배지가 올라간다</strong></li>\n<li>유형: <code>공지사항</code> / <code>마케팅</code> / <code>시스템(자동)</code></li>\n<li>열: 발송일시 · 유형 · 대상 · 내용 · 읽음</li>\n</ul>"}, "s11-2": {"t": "11-2. 미결", "h": "<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>현재</th>\n  <th>정해야 할 것</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>휴대폰 푸시</td>\n  <td>없음 — <strong>앱을 켜 둔 동안에만</strong> 전달</td>\n  <td>포인트 소멸처럼 꼭 닿아야 할 알림의 전달 수단</td>\n</tr>\n<tr>\n  <td>예약 발송·세그먼트</td>\n  <td>없음</td>\n  <td>다음 버전</td>\n</tr>\n<tr>\n  <td>수신 동의 연동</td>\n  <td>없음</td>\n  <td><strong>광고성 알림은 동의자에게만</strong> 보내는 규칙</td>\n</tr>\n<tr>\n  <td>보관 기간</td>\n  <td>화면에는 「90일 보관」이나 <strong>지우는 기능이 없다</strong>(최근 100건 표시)</td>\n  <td>문구 수정 또는 삭제 기능</td>\n</tr>\n<tr>\n  <td>확인 주기</td>\n  <td><strong>5초마다</strong> 확인 (시연용)</td>\n  <td>회원 수만큼 서버 부담 — 주기 상향 또는 푸시 전환</td>\n</tr>\n</tbody>\n</table>\n<hr />"}, "s12": {"t": "제12조 (설정)", "h": "<p>값을 바꾸면 <strong>고객 화면에 바로 반영</strong>된다.</p>\n<p>| 키 | 현재 값 | 뜻 |\n|---|---:|---|\n| <code>attend_point</code> | 10 | 출석 1회 적립 포인트 |\n| <code>attend_card_size</code> | 6 | 출석 카드 칸 수 |\n| <code>quiz_count</code> | 3 | 1일 출제 문항 수 |\n| <code>quiz_point</code> | 10 | 퀴즈 문항당 포인트 |\n| <code>quiz_allow_repeat</code> | 0 | <strong>푼 문제 다시 출제 허용</strong> — 고르기 「끔 — 푼 문항은 다시 내지 않음」/「켬 — 푼 문항도 다시 출제」 (「적립」 묶음) |\n| <code>offer_point</code> | 10 | 오퍼월 클릭 기본 포인트 — <strong>새 혜택 등록 창의 「적립 포인트」 기본값</strong>(광고마다 넣은 값이 우선) <em>(10-28 크로스체크 — 대화창4)</em> Q5 |\n| <code>offer_dwell</code> | 3 | 오퍼월 체류 조건(초) — <strong>새 혜택 등록 창의 「체류(초)」 기본값</strong> <em>(10-28 크로스체크 — 대화창4)</em> Q5 |\n| <code>draw_w1</code> | 45 | 출석 보너스 10~20P 비중(%) |\n| <code>draw_w2</code> | 30 | 출석 보너스 21~40P 비중(%) |\n| <code>draw_w3</code> | 18 | 출석 보너스 41~70P 비중(%) |\n| <code>draw_w4</code> | <strong>7</strong> | 출석 보너스 71~100P 비중(%) — <strong>하한</strong> (설명 「7% 미만 불가(자사 기준)」) |\n| <code>invite_point</code> | 1,000 | 친구 추천 양방 각 포인트 |\n| <code>invite_cap</code> | <strong>3</strong> | 친구 추천 적립 상한 (<strong>정책 원안 월 20회 · 시연용 3회</strong>) |\n| <code>withdraw_unit</code> | 1,000 | 출금 단위(P) |\n| <code>withdraw_min</code> | 10,000 | 출금 최소 신청액(P) |\n| <code>withdraw_max_once</code> | 100,000 | 출금 1회 한도(P) |\n| <del><code>expire_days</code></del> | 365 | 포인트 소멸 기간(일) — <strong>설정 화면에서 숨김</strong>. 약관 9-6 「12개월」로 정한 값이라 운영자가 화면에서 바꾸면 약관과 어긋난다(바꾸려면 약관 개정) <em>(10-28 크로스체크 — 대화창4)</em> | <code>[PO 확정 2026-10-28]</code> Q5 |\n| <code>max_users</code> | 0 | 가입 가능 인원 (0 = 제한 없음) |\n| <code>draw_base_rate</code> | 1 | 예약 기본 적립 요율(%) |\n| <code>draw_expire_days</code> | <strong>30</strong> | 뽑기 가능 기간(일) — <strong>적립완료일 + 30일</strong> · 0 = 무기한 <code>[PO 확정 2026-10-27]</code> |\n| <code>admin_pw</code> | — | 어드민 비밀번호 |</p>\n<h3 id=\"s12-1\">12-1. 출석 보너스 하한 7%</h3>\n<p>최고 구간(71~100P)의 비중을 <strong>7% 미만으로 내리지 못하게</strong> 막아 두었다.</p>\n<blockquote>\n<p>⚠️ <strong>이 7%는 법으로 정해진 수치가 아니다.</strong>\n표시광고법은 <strong>구체적인 비율을 규정하지 않는다.</strong>\n「최대 100P」라고 알리면서 그 확률이 지나치게 낮으면 문제가 될 수 있다는 판단에서\n<strong>자사 기준으로 정한 값</strong>이다. <code>미결</code> — 법무 검토 필요.</p>\n</blockquote>\n<h3 id=\"s12-2\">12-2. 데이터 초기화 (시연 전용)</h3>\n<ul>\n<li><strong>포인트·기록만 초기화</strong> / <strong>전부 초기화(회원까지)</strong></li>\n<li>시연 반복을 위한 기능이다. <strong>상용에서는 제거한다.</strong></li>\n</ul>\n<h3 id=\"s12-3\">12-3. 저장할 때 검사 <em>(v0.2 신설)</em></h3>\n<p><strong>하나라도 틀리면 아무것도 저장하지 않는다.</strong></p>\n<table>\n<thead>\n<tr>\n  <th>검사</th>\n  <th>거절 문구</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>숫자가 아님</td>\n  <td>「{항목} — 숫자로 입력해 주세요」</td>\n</tr>\n<tr>\n  <td>칸별 범위 밖 (아래 표)</td>\n  <td>「{항목} — {최소}~{최대} 사이로 입력해 주세요」</td>\n</tr>\n<tr>\n  <td>출석 보너스 네 칸 <strong>합계 ≠ 100</strong></td>\n  <td>「출석 보너스 비중 네 칸의 합이 100이어야 해요 (지금 N)」 — 서버는 합계 대비 비율로 뽑으므로, 다른 칸을 올리면 71~100P 실제 비중이 7% 밑으로 내려간다(예: 90·30·18·7 → 4.8%)</td>\n</tr>\n<tr>\n  <td>71~100P <strong>7% 미만</strong></td>\n  <td>「71~100P 구간은 7% 미만으로 낮출 수 없어요 (자사 기준 · 정책서 2-5절)」</td>\n</tr>\n<tr>\n  <td>출금 최소 &lt; 출금 단위</td>\n  <td>「출금 최소 신청액은 출금 단위보다 작을 수 없어요」</td>\n</tr>\n<tr>\n  <td>1회 한도 &lt; 최소</td>\n  <td>「출금 1회 한도는 최소 신청액보다 작을 수 없어요」</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>출석 보너스 묶음 아래에 <strong>합계를 입력할 때마다</strong> 보여준다 — 「합계 100 ✓」 / 「합계 N — 100이 되어야 저장돼요」(빨강)</li>\n</ul>\n<p><strong>칸별 허용 범위</strong> — 정책값이 아니라 <strong>「말이 안 되는 값」을 막는 울타리</strong>다 (대화창4 설정 · PO 확인 권장)</p>\n<table>\n<thead>\n<tr>\n  <th>키</th>\n  <th>범위</th>\n  <th>키</th>\n  <th>범위</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><code>attend_point</code></td>\n  <td>1~10,000</td>\n  <td><code>invite_point</code></td>\n  <td>1~1,000,000</td>\n</tr>\n<tr>\n  <td><code>attend_card_size</code></td>\n  <td>2~14</td>\n  <td><code>invite_cap</code></td>\n  <td>0~10,000</td>\n</tr>\n<tr>\n  <td><code>quiz_count</code></td>\n  <td>1~10</td>\n  <td><code>withdraw_unit</code></td>\n  <td>1~1,000,000</td>\n</tr>\n<tr>\n  <td><code>quiz_point</code></td>\n  <td>1~10,000</td>\n  <td><code>withdraw_min</code></td>\n  <td>1~10,000,000</td>\n</tr>\n<tr>\n  <td><code>quiz_allow_repeat</code></td>\n  <td>0~1</td>\n  <td><code>withdraw_max_once</code></td>\n  <td>1~100,000,000</td>\n</tr>\n<tr>\n  <td><code>offer_point</code></td>\n  <td>1~100,000</td>\n  <td><code>expire_days</code></td>\n  <td>1~3,650</td>\n</tr>\n<tr>\n  <td><code>offer_dwell</code></td>\n  <td>0~600</td>\n  <td><code>max_users</code></td>\n  <td>0~100,000,000</td>\n</tr>\n<tr>\n  <td><code>draw_w1</code>~<code>draw_w4</code></td>\n  <td>0~100</td>\n  <td><code>draw_base_rate</code></td>\n  <td>0~100</td>\n</tr>\n<tr>\n  <td></td>\n  <td></td>\n  <td><code>draw_expire_days</code></td>\n  <td>0~3,650</td>\n</tr>\n</tbody>\n</table>\n<hr />"}, "s12-1": {"t": "12-1. 출석 보너스 하한 7%", "h": "<p>최고 구간(71~100P)의 비중을 <strong>7% 미만으로 내리지 못하게</strong> 막아 두었다.</p>\n<blockquote>\n<p>⚠️ <strong>이 7%는 법으로 정해진 수치가 아니다.</strong>\n표시광고법은 <strong>구체적인 비율을 규정하지 않는다.</strong>\n「최대 100P」라고 알리면서 그 확률이 지나치게 낮으면 문제가 될 수 있다는 판단에서\n<strong>자사 기준으로 정한 값</strong>이다. <code>미결</code> — 법무 검토 필요.</p>\n</blockquote>"}, "s12-2": {"t": "12-2. 데이터 초기화 (시연 전용)", "h": "<ul>\n<li><strong>포인트·기록만 초기화</strong> / <strong>전부 초기화(회원까지)</strong></li>\n<li>시연 반복을 위한 기능이다. <strong>상용에서는 제거한다.</strong></li>\n</ul>"}, "s12-3": {"t": "12-3. 저장할 때 검사 (v0.2 신설)", "h": "<p><strong>하나라도 틀리면 아무것도 저장하지 않는다.</strong></p>\n<table>\n<thead>\n<tr>\n  <th>검사</th>\n  <th>거절 문구</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>숫자가 아님</td>\n  <td>「{항목} — 숫자로 입력해 주세요」</td>\n</tr>\n<tr>\n  <td>칸별 범위 밖 (아래 표)</td>\n  <td>「{항목} — {최소}~{최대} 사이로 입력해 주세요」</td>\n</tr>\n<tr>\n  <td>출석 보너스 네 칸 <strong>합계 ≠ 100</strong></td>\n  <td>「출석 보너스 비중 네 칸의 합이 100이어야 해요 (지금 N)」 — 서버는 합계 대비 비율로 뽑으므로, 다른 칸을 올리면 71~100P 실제 비중이 7% 밑으로 내려간다(예: 90·30·18·7 → 4.8%)</td>\n</tr>\n<tr>\n  <td>71~100P <strong>7% 미만</strong></td>\n  <td>「71~100P 구간은 7% 미만으로 낮출 수 없어요 (자사 기준 · 정책서 2-5절)」</td>\n</tr>\n<tr>\n  <td>출금 최소 &lt; 출금 단위</td>\n  <td>「출금 최소 신청액은 출금 단위보다 작을 수 없어요」</td>\n</tr>\n<tr>\n  <td>1회 한도 &lt; 최소</td>\n  <td>「출금 1회 한도는 최소 신청액보다 작을 수 없어요」</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>출석 보너스 묶음 아래에 <strong>합계를 입력할 때마다</strong> 보여준다 — 「합계 100 ✓」 / 「합계 N — 100이 되어야 저장돼요」(빨강)</li>\n</ul>\n<p><strong>칸별 허용 범위</strong> — 정책값이 아니라 <strong>「말이 안 되는 값」을 막는 울타리</strong>다 (대화창4 설정 · PO 확인 권장)</p>\n<table>\n<thead>\n<tr>\n  <th>키</th>\n  <th>범위</th>\n  <th>키</th>\n  <th>범위</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><code>attend_point</code></td>\n  <td>1~10,000</td>\n  <td><code>invite_point</code></td>\n  <td>1~1,000,000</td>\n</tr>\n<tr>\n  <td><code>attend_card_size</code></td>\n  <td>2~14</td>\n  <td><code>invite_cap</code></td>\n  <td>0~10,000</td>\n</tr>\n<tr>\n  <td><code>quiz_count</code></td>\n  <td>1~10</td>\n  <td><code>withdraw_unit</code></td>\n  <td>1~1,000,000</td>\n</tr>\n<tr>\n  <td><code>quiz_point</code></td>\n  <td>1~10,000</td>\n  <td><code>withdraw_min</code></td>\n  <td>1~10,000,000</td>\n</tr>\n<tr>\n  <td><code>quiz_allow_repeat</code></td>\n  <td>0~1</td>\n  <td><code>withdraw_max_once</code></td>\n  <td>1~100,000,000</td>\n</tr>\n<tr>\n  <td><code>offer_point</code></td>\n  <td>1~100,000</td>\n  <td><code>expire_days</code></td>\n  <td>1~3,650</td>\n</tr>\n<tr>\n  <td><code>offer_dwell</code></td>\n  <td>0~600</td>\n  <td><code>max_users</code></td>\n  <td>0~100,000,000</td>\n</tr>\n<tr>\n  <td><code>draw_w1</code>~<code>draw_w4</code></td>\n  <td>0~100</td>\n  <td><code>draw_base_rate</code></td>\n  <td>0~100</td>\n</tr>\n<tr>\n  <td></td>\n  <td></td>\n  <td><code>draw_expire_days</code></td>\n  <td>0~3,650</td>\n</tr>\n</tbody>\n</table>\n<hr />"}, "s13": {"t": "제13조 (관리자 로그)", "h": "<h3 id=\"s13-1\">13-1. 기록되는 작업</h3>\n<table>\n<thead>\n<tr>\n  <th>코드</th>\n  <th>작업</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><code>point_grant</code></td>\n  <td>포인트 수동 지급·회수</td>\n</tr>\n<tr>\n  <td><code>withdraw_paid</code></td>\n  <td>출금 지급 처리</td>\n</tr>\n<tr>\n  <td><code>reject_wd</code></td>\n  <td>출금 반려</td>\n</tr>\n<tr>\n  <td><code>order_reissue</code></td>\n  <td>쿠폰 재발행</td>\n</tr>\n<tr>\n  <td><code>offer_edit</code></td>\n  <td>혜택 등록·수정</td>\n</tr>\n<tr>\n  <td><code>quiz_edit</code></td>\n  <td>퀴즈 등록·수정</td>\n</tr>\n<tr>\n  <td><code>adv_edit</code></td>\n  <td>광고주 등록·수정</td>\n</tr>\n<tr>\n  <td><code>notify</code></td>\n  <td>알림 발송</td>\n</tr>\n<tr>\n  <td><code>setting</code></td>\n  <td>설정값 변경</td>\n</tr>\n<tr>\n  <td><code>reset</code></td>\n  <td>데이터 초기화</td>\n</tr>\n<tr>\n  <td><code>verify</code></td>\n  <td>본인인증 처리 — 완료로 바꾸면 적립대기 지급액을 함께 남긴다 <em>(v0.2)</em></td>\n</tr>\n</tbody>\n</table>\n<p>열: 일시 · 관리자 · 작업 · 대상 · 내용</p>\n<h3 id=\"s13-2\">13-2. 미결</h3>\n<blockquote>\n<p><strong>누가 했는지 구분되지 않는다.</strong> 비밀번호 하나로 들어오기 때문이다.\n권한 체계(2-2)와 함께 정해야 한다.</p>\n</blockquote>\n<hr />"}, "s13-1": {"t": "13-1. 기록되는 작업", "h": "<table>\n<thead>\n<tr>\n  <th>코드</th>\n  <th>작업</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><code>point_grant</code></td>\n  <td>포인트 수동 지급·회수</td>\n</tr>\n<tr>\n  <td><code>withdraw_paid</code></td>\n  <td>출금 지급 처리</td>\n</tr>\n<tr>\n  <td><code>reject_wd</code></td>\n  <td>출금 반려</td>\n</tr>\n<tr>\n  <td><code>order_reissue</code></td>\n  <td>쿠폰 재발행</td>\n</tr>\n<tr>\n  <td><code>offer_edit</code></td>\n  <td>혜택 등록·수정</td>\n</tr>\n<tr>\n  <td><code>quiz_edit</code></td>\n  <td>퀴즈 등록·수정</td>\n</tr>\n<tr>\n  <td><code>adv_edit</code></td>\n  <td>광고주 등록·수정</td>\n</tr>\n<tr>\n  <td><code>notify</code></td>\n  <td>알림 발송</td>\n</tr>\n<tr>\n  <td><code>setting</code></td>\n  <td>설정값 변경</td>\n</tr>\n<tr>\n  <td><code>reset</code></td>\n  <td>데이터 초기화</td>\n</tr>\n<tr>\n  <td><code>verify</code></td>\n  <td>본인인증 처리 — 완료로 바꾸면 적립대기 지급액을 함께 남긴다 <em>(v0.2)</em></td>\n</tr>\n</tbody>\n</table>\n<p>열: 일시 · 관리자 · 작업 · 대상 · 내용</p>"}, "s13-2": {"t": "13-2. 미결", "h": "<blockquote>\n<p><strong>누가 했는지 구분되지 않는다.</strong> 비밀번호 하나로 들어오기 때문이다.\n권한 체계(2-2)와 함께 정해야 한다.</p>\n</blockquote>\n<hr />"}, "s14": {"t": "제14조 (미결 사항 모아보기)", "h": "<table>\n<thead>\n<tr>\n  <th style=\"text-align:center\">#</th>\n  <th>항목</th>\n  <th>지금 상태</th>\n  <th>정해야 할 것</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:center\">1</td>\n  <td><strong>어드민 권한·계정</strong></td>\n  <td>비밀번호 1개</td>\n  <td>계정 발급 · 등급 · <strong>처리자 기록</strong></td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">2</td>\n  <td><strong>포인트 수동 처리 통제</strong></td>\n  <td>제한 없음</td>\n  <td>권한 · 1회 한도 · 승인 절차</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">3</td>\n  <td><strong>출금 승인 단계</strong></td>\n  <td>없음</td>\n  <td>일정 금액 이상 승인 여부</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">4</td>\n  <td><strong>출금 월 한도</strong></td>\n  <td>고객 화면에만 존재</td>\n  <td>설정값으로 옮기고 <strong>서버 검증</strong></td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">5</td>\n  <td><strong>출금 수수료</strong></td>\n  <td>「정책 미확정」 노출 중</td>\n  <td>자사 부담 vs 신청액에서 차감</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">6</td>\n  <td><strong>원천징수·세무</strong></td>\n  <td>없음</td>\n  <td>현금 지급의 세무 기준</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">7</td>\n  <td><strong>쿠폰 발행사</strong></td>\n  <td>자사 생성</td>\n  <td>발행 업체 선정 · 재고·정산 연동</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">8</td>\n  <td><strong>광고주 정산</strong></td>\n  <td>등록만</td>\n  <td>CPC/CPA 요율 · 주기 · 세금계산서</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">9</td>\n  <td><strong>출석 보너스 7% 하한</strong></td>\n  <td>자사 기준</td>\n  <td><strong>법무 검토</strong></td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">10</td>\n  <td><strong>친구 추천 상한</strong></td>\n  <td>시연 3회</td>\n  <td>원안 월 20회로 되돌릴지</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\"><del>11</del></td>\n  <td><del>뽑기 가능 기간</del></td>\n  <td><strong>해소 2026-10-27 — 30일 확정</strong></td>\n  <td>포인트 정책서 v0.2 4절</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">12</td>\n  <td><strong>퀴즈 출제 근거</strong></td>\n  <td>운영 기준으로 관리</td>\n  <td>사실 확인을 무엇으로 담보할지</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">13</td>\n  <td><strong>퀴즈 문항별 광고 표기</strong></td>\n  <td>v0.6 신설</td>\n  <td>적립 화면 광고의 <strong>표기 의무</strong></td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">14</td>\n  <td><strong>알림 보관 90일</strong></td>\n  <td>문구만 있고 <strong>기능 없음</strong></td>\n  <td>문구 수정 또는 삭제 기능</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">15</td>\n  <td><strong>알림 수신 동의 연동</strong></td>\n  <td>없음</td>\n  <td>광고성 알림 발송 규칙</td>\n</tr>\n<tr>\n  <td style=\"text-align:center\">16</td>\n  <td><strong>개인정보 반출</strong></td>\n  <td>엑셀 내려받기 없음</td>\n  <td>반출 기준 수립 후 개방 여부</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h2>부록 A. 시연용으로 만든 것 — 상용 전 제거·전환 대상</h2>\n<table>\n<thead>\n<tr>\n  <th>대상</th>\n  <th>현재</th>\n  <th>상용에서</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>출금 지급</td>\n  <td>운영자가 [지급하기]</td>\n  <td><strong>펌뱅킹 자동 송금</strong></td>\n</tr>\n<tr>\n  <td>픽샵 쿠폰</td>\n  <td>자사 생성 번호</td>\n  <td><strong>발행 업체 연동</strong></td>\n</tr>\n<tr>\n  <td>예약 생성</td>\n  <td>고객이 [예약 완료 처리]</td>\n  <td><strong>호텔스컴바인 예약 결과 수신</strong></td>\n</tr>\n<tr>\n  <td>데이터 초기화</td>\n  <td>메뉴에 있음</td>\n  <td><strong>제거</strong></td>\n</tr>\n<tr>\n  <td>친구 추천 상한</td>\n  <td>3회</td>\n  <td>정책 원안 값</td>\n</tr>\n<tr>\n  <td>알림 확인 주기</td>\n  <td>5초</td>\n  <td>상향 또는 푸시</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h2>부록 B. 이 문서와 설명서의 관계</h2>\n<table>\n<thead>\n<tr>\n  <th>문서</th>\n  <th>성격</th>\n  <th>읽는 사람</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>이 문서</strong></td>\n  <td>개발·운영 <strong>기준</strong>. 절 번호·값·미결</td>\n  <td>개발자 · 기획</td>\n</tr>\n<tr>\n  <td><code>설명서/admin.html</code></td>\n  <td>같은 내용을 <strong>읽히기 위한 글</strong>로 쓴 것. 화면 캡처 중심</td>\n  <td>CPO · 대표 · 이해관계자</td>\n</tr>\n</tbody>\n</table>\n<p>어드민 각 화면의 안내 띠는 <strong>설명서</strong>(https://dreamyuns.github.io/new-brand/guide/admin.html)로 연결된다.\n<strong>두 문서의 내용이 어긋나면 이 문서를 기준으로 설명서를 고친다.</strong></p>"}}};
